char	**input_array;
//****************
int	row_len = 0;
int	row_count = 0;
//******************
int	i;
int	j;
//******************
int	xmas = 0;
//******************
char	**ft_split(char const *s, char c);
//******************

void	check_Mup()
{
	if ((j-1) >= 0 && (i-1) >= 0 && input_array[i-1][j-1] == 'M' && (j+2) <= row_len && (i-1) >= 0 && input_array[i-1][j+1] == 'M'
		&& (j-1) >= 0 && (i+2) <= row_count && input_array[i+1][j-1] == 'S' && (j+2) <= row_len && (i+2) <= row_count && input_array[i+1][j+1] == 'S')
	{
				xmas++;
	}
}
void	check_Mdown()//
{
	if ((j-1) >= 0 && (i-1) >= 0 && input_array[i-1][j-1] == 'S' && (j+2) <= row_len && (i-1) >= 0 && input_array[i-1][j+1] == 'S'
		&& (j-1) >= 0 && (i+2) <= row_count && input_array[i+1][j-1] == 'M' && (j+2) <= row_len && (i+2) <= row_count && input_array[i+1][j+1] == 'M')
	{
				xmas++;
	}
}
void	check_Mleft()//
{
	if ((j-1) >= 0 && (i-1) >= 0 && input_array[i-1][j-1] == 'M' && (j+2) <= row_len && (i-1) >= 0 && input_array[i-1][j+1] == 'S'
		&& (j-1) >= 0 && (i+2) <= row_count && input_array[i+1][j-1] == 'M' && (j+2) <= row_len && (i+2) <= row_count && input_array[i+1][j+1] == 'S')
	{
				xmas++;
	}
}
void	check_Mright()//
{
	if ((j-1) >= 0 && (i-1) >= 0 && input_array[i-1][j-1] == 'S' && (j+2) <= row_len && (i-1) >= 0 && input_array[i-1][j+1] == 'M'
		&& (j-1) >= 0 && (i+2) <= row_count && input_array[i+1][j-1] == 'S' && (j+2) <= row_len && (i+2) <= row_count && input_array[i+1][j+1] == 'M')
	{
				xmas++;
	}
}






int	main()
{	
	i = 0;
	while (input[i] != ':')
	{
		row_len++;
		i++;
	}
	
	//********************
	printf("row_len: %d\n", row_len);
	//********************
	
	
	i = 0;
	while (input[i] != '\0')
	{
		if (input[i+1] == ':' || input[i+1] == '\0')
		{
			row_count++;
		}
		i++;
	}
	
	//*******************
	printf("row_count: %d\n", row_count);
	
	input_array = ft_split(input, ':');
	
	i = 0;
	j = 0;
	
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
			//encontramos uuna coinidencia
			if (input_array[i][j] == 'A')
			{
				
				
				check_Mup();
				
				check_Mdown();
				
				check_Mleft();
				
				check_Mright();
			}
			
			
			
			
			
			j++;
		}
		
		
		
		
		
		
		
		
		
		
		
		i++;
	}
	
	printf("%d", xmas);
}
